function siftDown(a,i,n){ while(true){ var l=2*i+1, r=2*i+2, s=i;
    if(l<n && a[l]<a[s]) s=l; if(r<n && a[r]<a[s]) s=r; if(s===i) break;
    var t=a[i]; a[i]=a[s]; a[s]=t; i=s; } }
function heapify(arr){ var a=arr.slice(); for(var i=Math.floor(a.length/2)-1;i>=0;i--) siftDown(a,i,a.length); return a; }
function push(a,x){ a.push(x); var i=a.length-1; while(i>0){ var p=(i-1)>>1; if(a[p]<=a[i]) break; var t=a[i]; a[i]=a[p]; a[p]=t; i=p; } return a; }
function pop(a){ if(a.length===0) return null; var top=a[0], last=a.pop(); if(a.length>0){ a[0]=last; siftDown(a,0,a.length); } return top; }
var EXPORTS={heapify:heapify, push:push, pop:pop, siftDown:siftDown};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HeapifyForgePure = EXPORTS; }
